import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_scale_bn_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_scale_bn_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float scale_factor,
    float eps,
    int N,
    int C,
    int D,
    int H,
    int W
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int size = N * C * D * H * W;
    if (idx < size) {
        int w = idx % W;
        int tmp = idx / W;
        int h = tmp % H; tmp /= H;
        int d = tmp % D; tmp /= D;
        int c = tmp % C; tmp /= C;
        int n = tmp;

        float val = input[idx] * scale_factor;
        float mean_val = mean[c];
        float var_val = var[c];
        float gamma_val = gamma[c];
        float beta_val = beta[c];

        float norm = (val - mean_val) / sqrtf(var_val + eps);
        output[idx] = gamma_val * norm + beta_val;
    }
}

torch::Tensor fused_scale_bn_cuda(
    torch::Tensor input,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor weight,
    torch::Tensor bias,
    float scale_factor,
    float eps
) {
    auto N = input.size(0);
    auto C = input.size(1);
    auto D = input.size(2);
    auto H = input.size(3);
    auto W = input.size(4);
    auto output = torch::empty_like(input);

    int block_size = 256;
    int grid_size = (input.numel() + block_size - 1) / block_size;

    fused_scale_bn_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        scale_factor,
        eps,
        N, C, D, H, W
    );
    return output;
}
""";

