global_avg_pool_3d_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void global_avg_pool_3d_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N,
    int C,
    int D,
    int H,
    int W
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int size = N * C;
    if (idx < size) {
        int c = idx % C;
        int n = idx / C;

        float sum_val = 0.0f;
        int offset = ((n * C + c) * D) * H * W;
        for(int dd = 0; dd < D; dd++){
            for(int hh = 0; hh < H; hh++){
                for(int ww = 0; ww < W; ww++){
                    sum_val += input[offset + dd*H*W + hh*W + ww];
                }
            }
        }
        sum_val /= (D * H * W);
        output[idx] = sum_val;
    }
}

torch::Tensor global_avg_pool_3d_cuda(torch::Tensor input) {
    auto N = input.size(0);
    auto C = input.size(1);
    auto D = input.size(2);
    auto H = input.size(3);
    auto W = input.size(4);

    auto output = torch::zeros({N, C, 1, 1, 1}, input.options());

    int block_size = 256;
    int grid_size = (N * C + block_size - 1) / block_size;

    global_avg_pool_3d_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, D, H, W
    );
    return output;
}
""";

global_avg_pool_3d_cpp_source = r"""
torch::Tensor global_avg_pool_3d_cuda(torch::Tensor input);
""";

fused_scale_bn = load_inline(
    name="fused_scale_bn",
    cpp_sources=fused_scale_bn_cpp_source,
    cuda_sources=fused_scale_bn_source,
    functions=["fused_scale_bn_cuda"],
    verbose=False,
    extra_cflags=[],
    extra_ldflags=[]
)

gap_3d = load_inline(
    name="global_avg_pool_3d",
    cpp_sources=global_avg_pool_3d_cpp_source,
    cuda_sources=global_avg_pool_3d_source,
    functions=["global_avg_pool_3d_cuda"],
    verbose=False,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    """
    Optimized model with custom CUDA kernels for scale+BN and global average pooling.
    """
    def __init__(self, in_channels, out_channels, kernel_size, scale_factor, eps=1e-5, momentum=0.1):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size)
        self.batch_norm = nn.BatchNorm3d(out_channels, eps=eps, momentum=momentum)
        self.scale_factor = scale_factor
        self.fused_scale_bn = fused_scale_bn
        self.gap_3d = gap_3d

    def forward(self, x):
        x = self.conv_transpose(x)
        x = self.fused_scale_bn.fused_scale_bn_cuda(
            x,
            self.batch_norm.running_mean,
            self.batch_norm.running_var,
            self.batch_norm.weight,
            self.batch_norm.bias,
            self.scale_factor,
            self.batch_norm.eps
        )
        x = self.gap_3d.global_avg_pool_3d_cuda(x)
        return x
